  AwakerTalent_122607_TalentDesc_1 = {
    Text = "·Каждый раз после разыгрывания 2 карт «ударить», «Мушетт» проводит Погоня, случайно нанося 1 Удар, равный 30% атакующей силы «Мушетт», и считается как «ударить». Максимум 4 раза за ход."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "Драматическая встреча"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·Этот талант действует только на уровнях «Звёздной главы».\n·Тело, атака и защита данного Пробуждённого повышаются на [Arg1] %, а после первого разыгрывания Возвышения данный Пробуждённый получает [Arg2] единиц Ключесвета.\n·Эффект Яда, применяемый всеми Пробуждёнными, повышается на [Arg3]%.\n·Каждый слой «Очарования» дополнительно снижает урон, наносимый врагами типа «Гуманоид», на 1%, а при снятии дополнительно наносит врагам типа «Гуманоид» чистый урон в размере 1% от макс. ОЗ."
  },
