  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·Когда Арахна в команде, заменяет царство «Ультра» на царство «Сингулярность: Ультра».\n·Пространственный скачок: эффект срабатывает после первого разыгрывания Командной карты за ход — помещает её временную Базовую копию в Ультра пространство и наделяет её и временную копию 25 уровнями «Маяка сингулярности»; в Ультра ход этот эффект не активируется.\n·Маяк сингулярности: каждый уровень повышает итоговый эффект урона, фиксированной Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки этой карты на 2%, а итоговый эффект фиксированного Щита, фиксированного Лечения ОЗ, Силы▼ — на 1%; снимается после разыгрывания. Карты с Маяком сингулярности не могут активировать «Пространственный скачок».\n·Ультра пространство: когда Ультра пространство достигает предела, вместо получения дополнительного хода в конце хода активируется Ультра пространство: дополнительный ход больше не предоставляется, незакреплённые карты из Руки сбрасываются и активируется эффект Ускользания, все карты из Ультра пространства помещаются в Руку, текущая Арифметика устанавливается на 5. После активации Ультра пространства текущий ход считается Ультра ходом.\n·«Аннигиляция сингулярности»: извлечь крайнюю левую карту из Ультра пространства. Перезарядка 3 хода.\n·После начала исследования Усиление урона команды +50%, и получить 15 уровней «Призмы сингулярности».\n·«Призма сингулярности»: все Командные карты считаются имеющими равное количество уровней Маяка сингулярности.\n·Мастерство Ультра: каждая единица Мастерства царства команды повышает количество уровней «Маяка сингулярности», накладываемых «Призмой сингулярности» и «Пространственным скачком», на 0.05%.\n·Чистый сверхразмерный: если команда состоит только из Ультра или Хаос Пробуждённых, эффект Мастерства Ультра и Усиление урона от царства удваиваются."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Нити судьбы"
  },
