  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·Этот талант действует только на уровнях «Звёздного Царства».\n·Тело, атака и защита данного пробуждённого повышаются на [Arg1]%, а после первого розыгрыша Возвышения этот пробуждённый получает [Arg2] единиц Ключесвета.\n·Пробуждённый, выбранный «Песней Саи», получает [Arg3] зарядов «Фиесты размножения», а следующий Зов срабатывает 2 раза.\n·«Коррозия», наносимая Саей врагам типа «Каро», дополнительно увеличивается на [Arg4]%."
  },
  AwakerTalent_130398_TalentDesc_10 = {
    Text = "·Этот талант действует только на уровнях «Звёздного Царства».\n·Тело, атака и защита данного пробуждённого повышаются на [Arg1]%, а после первого розыгрыша Возвышения этот пробуждённый получает [Arg2] единиц Ключесвета.\n·Пробуждённый, выбранный «Песней Саи», получает [Arg3] зарядов «Фиесты размножения», а следующий Зов срабатывает 2 раза.\n·«Коррозия», наносимая Саей врагам типа «Каро», дополнительно увеличивается на [Arg4]%."
  },
  AwakerTalent_130398_TalentDesc_2 = {
    Text = "·Этот талант действует только на уровнях «Звёздного Царства».\n·Тело, атака и защита данного пробуждённого повышаются на [Arg1]%, а после первого розыгрыша Возвышения этот пробуждённый получает [Arg2] единиц Ключесвета.\n·Пробуждённый, выбранный «Песней Саи», получает [Arg3] зарядов «Фиесты размножения», а следующий Зов срабатывает 2 раза.\n·«Коррозия», наносимая Саей врагам типа «Каро», дополнительно увеличивается на [Arg4]%."
