  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·Этот талант действует только на уровнях «Звёздной главы».\n·Тело, атака и защита данного Пробуждённого повышаются на [Arg1]%, а после первого разыгрывания Возвышения данный Пробуждённый получает [Arg2] единиц Ключесвета.\n·Множитель эффекта Сила▼ и получаемый множитель силы «Безграничной дикой тени» повышаются на [Arg3]%; каждое срабатывание даёт следующему «Клинку скверны» дополнительный бонус силы [Arg4]%, максимум 1200%."
  },
