  AwakerTalent_131854_TalentDesc_1 = {
    Text = "·Когда Сая находится в команде, заменяет царство «Каро» на царство «Размножение: Каро».\n·Слияние Зародыша: Слияние Зародыша, получаемое каждый ход, повышается до 50~100, увеличиваясь по мере потери ОЗ, однако лимит слияния зародыша повышается со 100 до 200; при достижении лимита «Разведение эмбрионов» помещается в руку.\n·Разведение эмбрионов: при разыгрывании больше не даёт Крит. шанс, Поглощение также больше не даёт Щит и Временную силу▼. При первом использовании «Разведение эмбрионов» каждым Пробуждённым за ход получить 40 стаков «Фиесты размножения»: за каждый стак итоговый эффект следующего Вознесения этого Пробуждённого в текущем ходу — Урон, фиксированный Щит, фиксированное Лечение, фиксированная Сила, Сила▼, повышение Урона щупалец, фиксированный Яд, фиксированная Контратака — повышается на 1%.\n·Багровое горнило: количество автоматического накопления в начале хода изменяется на 10% потерянных ОЗ, максимальное накопление изменяется на 50% макс. ОЗ. В конце боя накопление прекращается, при использовании действует перезарядка 3 хода.\n·Алая эрозия: после использования Багрового горнила накладывает на всех врагов Коррозию в размере 1% от макс. ОЗ цели; чем больше потрачено Багрового горнила, тем сильнее эффект Коррозии, максимум +100%. На врагов типа «Пустая оболочка» наносит 5-кратный эффект Коррозии.\n·После начала исследования макс. ОЗ повышаются на 10%, Усиление урона команды +50%, в начале каждого хода все Пробуждённые получают 20 стаков «Фиесты размножения». Если команда состоит только из Пробуждённых Каро или Хаоса, Усиление урона от этого эффекта удваивается.\n·Мастерство царства становится «Мастерством Размножения: Каро»: каждая единица Мастерства царства повышает «Фиесту размножения», получаемую от «Размножения: Каро», на 0.05%.\n·Если команда состоит только из Пробуждённых Каро или Хаоса, эффект «Мастерства Размножения: Каро» удваивается."
  },
