  AwakerTalent_143615_TalentDesc_1 = {
    Text = "·Когда данный Персонаж находится в отряде, Царство «Эквор» заменяется Царством «Бентос: Эквор».\n·Базовый Урон щупалец изменяется на 5% от макс. ОЗ отряда.\n·После начала исследования Усиление урона отряда +50%. Если отряд состоит только из Пробуждённых Эквор или Хаос, данный эффект Усиления урона удваивается, однако в начале боя дополнительные щупальца больше не получаются.\n·Эффект «Скопление щупалец» больше не действует.\n·Стойка щупалец изменяется на «Бентос: Стойка щупалец».\n·«Бентос: Спокойное море»: получить Щит в размере 25% макс. ОЗ; в конце хода щупальца больше не атакуют; перезарядка 3 хода.\n·«Бентос: Девятый вал»: Урон щупалец в этом ходу становится 125%; После нанесения активного урона 1 Щупальце атакует, однако в конце хода теряется 1 Щупальце; перезарядка 3 хода.\n·Мастерство царства изменяется на «Бентос: Мастерство Эквор»: каждая единица Мастерства царства увеличивает Щит «Бентос: Спокойного моря» на 0.025% макс. ОЗ и дополнительно увеличивает Урон щупалец «Бентос: Девятого вала» на 0.025%.\n·Если отряд состоит только из Пробуждённых Эквор или Хаос, эффект «Бентос: Мастерство царства» удваивается."
  },
