  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Этот Талант действует только на уровнях «Звёздного Царства».\n·Тело, атака и защита этого Пробуждённого повышаются на [Arg1]%, а после первого разыгрывания Возвышения этим Пробуждённым он получает [Arg2] единиц Ключесвета.\n·«Клинок, разрывающий мир» дополнительно получает бонус [Arg3]% к Силе, после убийства врага получить [Arg4] Чёрных печатей с учётом собственного бонуса к выпадению печатей; в одном бою действует не более 1 раза."
  },
