  AwakerTalent_145718_TalentDesc_1 = {
    Text = "·Когда Карабу находится в команде, заменяет царство «Каро» на царство «Размножение: Каро».\n·Слияние Зародыша: Слияние Зародыша, получаемое каждый ход, повышается до 50~100, увеличиваясь по мере потери ОЗ, однако лимит слияния зародыша повышается со 100 до 200; при достижении лимита «Разведение эмбрионов» помещается в руку.\n·Разведение эмбрионов: при разыгрывании больше не даёт Крит. шанс, Поглощение также больше не даёт Щит и Временную силу▼. При первом использовании «Разведение эмбрионов» каждым Пробуждённым за ход получить 40 стаков «Фиесты размножения»: за каждый стак итоговый эффект следующего Вознесения этого Пробуждённого в текущем ходу — Урон, фиксированный Щит, фиксированное Лечение, фиксированная Сила, Сила▼, повышение Урона щупалец, фиксированный Яд, фиксированная Контратака — повышается на 1%.\n·Багровое горнило: количество автоматического накопления в начале хода изменяется на 10% потерянных ОЗ, максимальное накопление изменяется на 50% макс. ОЗ. В конце боя накопление прекращается, при использовании действует перезарядка 3 хода.\n·Алая эрозия: после использования Багрового горнила накладывает на всех врагов Коррозию в размере 1% от макс. ОЗ цели; чем больше потрачено Багрового горнила, тем сильнее эффект Коррозии, максимум +100%. На врагов типа «Пустая оболочка» наносит 5-кратный эффект Коррозии.\n·После начала исследования макс. ОЗ повышаются на 10%, Усиление урона команды +50%, в начале каждого хода все Пробуждённые получают 20 стаков «Фиесты размножения». Если команда состоит только из Пробуждённых Каро или Хаоса, Усиление урона от этого эффекта удваивается.\n·Мастерство царства становится «Мастерством Размножения: Каро»: каждая единица Мастерства царства повышает «Фиесту размножения», получаемую от «Размножения: Каро», на 0.05%.\n·Если команда состоит только из Пробуждённых Каро или Хаоса, эффект «Мастерства Размножения: Каро» удваивается."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Ложе чистоты"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·Когда Лотан: Китовластица в команде, заменяет царство «Хаос» на царство «Преисток: Хаос».\n·Первозданный прилив: базовый Ключесвет увеличивается до 2000 единиц, Усиление урона команды +50%, атака и защита всех Пробуждённых повышаются на 10%. Если команда состоит только из Хаос Пробуждённых, Усиление урона от этого эффекта удваивается. В начале боя получить 2000 единиц Ключесвета.\n·Слияние ключей: уровень заряда Ключесвета всех Пробуждённых становится равным среднему значению по команде. Ключесвет больше не получается за расход Арифметики, вместо этого каждый Пробуждённый получает Ключесвет за первую Командную карту каждого хода в размере «заряд Ключесвета этого Пробуждённого×3+100».\n·Неделимое царство: больше не активирует Чистый сверхразмерный, удвоение эффекта Мастерства и удвоение Усиления других царств.\n·Первозданное эхо: Возвышение получает Подготовку 1, при первом разыгрывании за ход автоматически высвобождает несомый Зов.\n·Осколки памяти: Зов заменяется на «Первозданная·Двойная реприза» и «Первозданная·Триада откровений», несомые Зовы не могут быть высвобождены самостоятельно.\n·Первозданная·Двойная реприза: из удерживаемых Зовов обнаружить 3 вида Зовов, выбрать 1 Зов и активировать его 2 раза.\n·Первозданная·Триада откровений: из удерживаемых Зовов обнаружить 3 группы Зовов, каждая состоит из 3 различных видов Зовов, выбрать одну группу и поочерёдно активировать каждый Зов в ней 1 раз.\n·Зовы в Первозданной·Двойной репризе и Первозданной·Триаде откровений будут включать восемь видов «Первозданной памяти».\n·Первозданная·Двойная реприза и Первозданная·Триада откровений считаются высвобождением 1 Зова; при многократном срабатывании действуют только на первый активированный Зов.\n·Мастерство царства становится «Первозданным·Мастерством Хаоса»: каждая единица Мастерства царства повышает силу Зова на 0.05%.\n·Каждая единица силы Зова повышает фиксированный Яд, фиксированную Контратаку, фиксированную Силу, фиксированный урон щупалец, фиксированные Угли былого на 2%, а также повышает фиксированный Щит, фиксированное Лечение ОЗ, Силу▼, Крит. шанс, Крит. урон, Усиление урона, Мастерство царства, Алиемус, Слияние Зародыша, Ключесвет на 1%.\n·Если команда состоит только из Хаос Пробуждённых, эффект «Первозданного·Мастерства Хаоса» удваивается."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Первозданное дыхание"
  },
