  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·Лили, ее снаряжение, Колесо Судьбы и ковенант каждый предоставляют 1% сопротивления смерти, базовый щит «Запретной топи» и «Базовой защиты» увеличивается на 0.25%, а накопление и предел терпения в Босс Битве увеличивается на 0.25%.\n·Когда Лили в команде, при потере 1 единицы здоровья получает 1 слой терпения, предел накопления терпения равен максимальному здоровью."
  },
