  },
  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·Предоставленный Сальвадором Эффект восстановления от печи получает бонус от увеличения восстановления жизни."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Пастырь душ"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·Рамона дополнительно получает 2.5 очка заряда серебряного ключа. Каждый Уровень согласованности дополнительно дает Рамоне 0.5 очка заряда серебряного ключа. \n·За каждую единицу уровня заряда серебряного ключа Базовый Урон \"Меча её величества\" увеличивается на 1%, а после разыгрывания вы получаете 0.75 временного мастерства областей."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Резонанс сердца и серебра"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·Рамона: Неизбывная дополнительно получает 2.5 уровня заряда серебряного ключа. Каждый Уровень согласованности дополнительно позволяет Рамоне получить 0.5 уровня заряда серебряного ключа. \n·Каждый Уровень заряда Ключесвета позволяет эффекту «Базовое ударение» Петли давать Рамоне 0.2% крит. шанса, а эффекту «Базовая защита» Петли давать Рамоне 0.2 Алиемуса."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Резонанс сердца и серебра"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·За каждые 1 очко мастерства в царстве у Нотила, контрудар от «Готовы и в бой» увеличивается на 0,25%."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "Ежедневное обслуживание"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "· За каждое 1% силы урона у Нимфея, базовый Эффект яда \"Похоронный звон\" и \"Мои собственные похороны\" увеличивается на 0.5%."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Погружение"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·Бой начинается, поместите 1 карту \"Одержимость\" в руку. \n ·Базовый Удар Мириам получает 100% бонус урона щупалец. \n ·Каждый раз, когда пробуждённый Мириам, Колесо Судьбы или ковенант увеличивают крит. Урон на 1%, Огромная Огромная сила Вознесения, Урон от щупалец, алиемус, а также наложение и активация эффекта яда повышаются на 0.2%."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Нерушимое Преданность"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·Тулу сам и экипированные судьбы и ковенанты обеспечивают по 1 уровню восстановления ярости, \"Базовый Удар\" получает 5% ущерба от щупалец и силы, а \"Приказ бездны\" получает 15% ущерба от щупалец и силы."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Власть бога-короля"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "·Санга, ее снаряжение, колесо судьбы и ковенант каждый предоставляют 1% сопротивления смерти, увеличивая алиемус, получаемый от «Базового удара» и «Базовой защиты», на 0.03, а «Утраченное искусство» дополнительно получает 0.15% критического шанса и критического урона."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Откровение смерти"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "· За каждое 1 очко уровня восстановления алиэмиуса у Куклы, эффекты восстановления жизни «Внешняя хирургия» и «Услуга за услугу» увеличиваются на 0.5%."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Деконструкция гнозиса"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "· За каждый 1% шанса выпадения черной Печать пакиа Огр, поэма «Семь искусств и добродетелей» временно увеличивает силу на 3%."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Бесформенная переплавка"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "· За каждое 1% сопротивления смерти у Альвы, Базовый Урон увеличивается на 0.5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Динамическое зрение"
  },
