  },
  AwakerTalent_54158_TalentDesc_1 = {
    Text = "· За каждый 1% критического шанса у Сорель, алиэмиус, полученный \"Базовой защитой\", увеличивается на 0.2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Страж помпезности"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·У Дженкина, его пробуждённый, Колесо Судьбы и ковенант за каждый 1% критического шанса увеличивают Базовый Урон \"Ударить\" и \"Браун в действии\" на 2%."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Общий враг"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·Эрика, её пробуждённое тело, Колесо Судьбы и ковенант, каждый раз предоставляя 1 очко уровня заряда серебряного ключа, \"Электромагнитный разряд\" позволяет Эрике получить 0.5% временного критического шанса и крит. урона."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Внешний Генезис энергии"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·В начале хода получите 1 Уровень Манока снов. \n·За каждый расход 1 уровня Манока снов атака контратаки, полученной \"Хранительницей заблудших\" и \"Некрополем грёз\", увеличивается на 5%. \n·За каждый 1% повышения урона, предоставляемого Вандой, Пробуждённым, судьбой и Ковенантом, Контратака, полученная \"Некрополем грёз\", увеличивается на 0.75%."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Откровение"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·Касия, пробуждённое тело, её Колесо Судьбы и ковенант каждый предоставляют 1 очко мастерства царства, \"Карнавал чудес\" увеличивает Базовый Урон Касии на 0.2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Мастер магии"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "· За каждый 1% шанса выпадения черной Печать пакиа у пробудившегося Тинкт, \"Аврора\" получает дополнительно 0.15% временного критического шанса."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Путешественник по планетам"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·«Основной Удар» и «Базовая защита» Орля также считаются Псалмами. При переходе Псалма эмоции переключаются, и эмоции могут напрямую влиять на Эффект этого Псалма. Разные эмоции приносят разные постоянные эффекты для команды. \n· За каждое 1% сопротивления смерти у Орли, Эффект увеличивается на 0.1% от начального значения."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Перо рождает чувство"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·С каждым 1% свойством сили усиленного урона, щит, создаваемый «Затерянным городом», увеличивается на 0,4%."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Одержимость возвращением"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "· За каждые 1% шанса выпадения черной Печать пакиа Цэкус получает 1% бонус к счётчику от \"Базового удара\"."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Бунтарские шипы"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·После розыгрыша карты приказа Селесте активирует 1 атаку щупальцем по врагу, за каждое 1 очко владения царством у Селесте, её личные, Колесо Судьбы и ковенант увеличивают Урон щупальцем данной активации на 0.5%."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Горн вояжа"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·За каждые 1% выпадения чёрной Печать пакиа у Сальвадора, максимальная жизнь алой печи увеличивается на 0,15%."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Начало жизни"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·За каждые 1% шанса выпадения чёрной Печать пакиа у Агриппы, её личные, снаряжённые Колесо Судьбы и ковенант увеличивают базовый щит «Бледное благословение» на 0.5% и базовый яд на 1%."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Печать пакиа"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·За каждые 1% сопротивления смерти у Фэйнт, Контратака, получаемая от «Колыбели звёзд» и «Безграничного звёздного света», увеличивается на 0.2%, а максимальный предел сопротивления смерти «Колыбели звёзд» увеличивается на 2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Вторичная Колыбель"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "· За каждое 1% силы урона у Илота, \"Выживший импас\" увеличивает Урон, наносимый в этом раунде, на 0.3%."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Печать боли"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·При убийстве врага Райкер получает 5 чёрных печатей, за каждые 1% выпадения чёрной Печать пакиа количество получаемых печатей увеличивается на 1%, максимум 5 раз за каждое исследование. \n·Получив 50/125/250 чёрных печатей в бою, лимит создания увеличивается на 1, в конце боя выберите одно <C05_zaowu:«Наследие Хаоса»>, чтобы добавить в список созданий."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Победитель получает всё"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·В битве с боссом, в начале хода и после использования Вознесения \"Расплавление · дора\", получить 1 Уровень \"Конец\". \"Конец\" может иметь максимум 10 уровней, при достижении 10 уровней положите 1 карту \"Конец иллюзий\" в руку."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Путь уничтожения"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Этот талант действует только в уровне «Звёздное Царство».\n·Телосложение, атака и защита этого пробуждённого увеличиваются на [Arg1] %, и после первой активации пробуждения гнозиса этот пробуждённый получает [Arg2] очков Ключесвета.\n·Каждое щупальце при атаке увеличивает временный Урон щупалец на [Arg3]% от атаки Тулу, максимум [Arg4] раз за ход.\n·Когда в отряде присутствуют другие 1/2/3 пробуждённых «Лимурии», Урон щупалец, получаемый всеми врагами, увеличивается на 10%/25%/50%."
