  AwakerTalent_74113_TalentDesc_1 = {
    Text = "·Этот талант действует только на уровнях «Звёздной главы».\n·Тело, атака и защита данного Пробуждённого повышаются на [Arg1]%, а после первого разыгрывания Возвышения данный Пробуждённый получает [Arg2] единиц Ключесвета.\n·«Кнут сумасшествия» получает Удержание и Подготовку. Активный урон Пандии по врагам, намеревающимся нанести урон, повышается на [Arg3]%; за каждую дополнительную атаку цели повышается на 5%, максимум на 20%."
