  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Этот талант активен только в уровне «Звёздное Царство».\n·У этого пробуждённого увеличиваются Тело, атака и защита на [Arg1] %, и после первого разыгрывания Возжигания ключесвета этот пробуждённый получает [Arg2] очков ключесвета.\n·Итоговый Урон «Удара» Лили увеличивается на [Arg3]%, в бою с боссом увеличение удваивается. После получения атаки от «сверхмерного» врага получает Эффект отложенного восстановления [Arg4]% потерянного от этой атаки здоровья. Эффект увеличения урона «Карающего удара» от «Терпения» получает [Arg5]% бонус усиления урона."
