  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Этот талант активен только в уровне «Звёздное Царство».\n·У этого пробуждённого увеличиваются Тело, атака и защита на [Arg1] %, и после первого разыгрывания Возжигания ключесвета этот пробуждённый получает [Arg2] очков ключесвета.\n·Базовый Эффект урона, накладываемый «Искуплением страданий», увеличивается на [Arg3] % от атаки Поллукса.\n·При каждом накоплении 50 слоёв «Печати греха» 1 Карта «Святое сердце» помещается в руку.\n·После достижения 100 слоёв «Печати греха», когда «Святое сердце» расходуется после 3-го разыгрывания, вытягивается 1 собственная «Карта навыка».\n·При нанесении урона Эффект «Печати греха» удваивается против врагов «Церкви Фонаря»."
  },
