  AwakerTalent_78620_TalentDesc_1 = {
    Text = "·Этот талант действует только на уровнях «Звёздной главы».\n·Тело, атака и защита данного Пробуждённого повышаются на [Arg1]%, а после первого разыгрывания Возвышения данный Пробуждённый получает [Arg2] единиц Ключесвета.\n·В начале боя полученный урон от щупалец всех врагов повышается на [Arg3]%; для врагов «Эквора» эффект удваивается. Активный урон «Карающих молний» по врагам «Эквора» повышается на [Arg4]%."
