  AwakerTalent_78622_TalentDesc_1 = {
    Text = "·Этот талант активен только в уровне «Звёздное Царство».\n·У этого пробуждённого увеличиваются Тело, атака и защита на [Arg1] %, и после первого разыгрывания Возжигания ключесвета этот пробуждённый получает [Arg2] очков энергии серебряного ключа.\n·Эффект усиления «Живого пламени» увеличивается на [Arg3] %, после начала хода и перед фазой сброса со всех карт в руке снимается «Горение», и за каждый слой Кэтигула получает 1 слой «Взрывного пламени»."
  },
