    Text = "·Этот талант действует только на уровнях «Звёздной главы».\n·Тело, атака и защита данного Пробуждённого повышаются на [Arg1]%, а после первого разыгрывания Возвышения данный Пробуждённый получает [Arg2] единиц Ключесвета.\n·Крит. шанс и Крит. урон Вознесения Карабу повышаются на [Arg3]%. Максимальный ОЗ, предоставляемый «Сытостью», повышается на [Arg5]%. На местности «Ледяные просторы» расход арифметики «Снежного заклятья» –1, количество ударов +1, а урон и эффект Слабости действуют на всех врагов."
