  AwakerTalent_78624_TalentDesc_1 = {
    Text = "·Этот талант активен только на уровнях «Звёздное Царство».\n·Тело, атака и защита этого Пробуждённого увеличиваются на [Arg1] %, а после первого использования Возжигания ключесвета этот Пробуждённый получает [Arg2] очков Ключесвета.\n·Разыгрывание «Ониксового пера» не добавляет «Арифметической гармонии», «Священные перья очищения» накладывают коррозию, увеличенную на [Arg3]% от АТК Кастора.\n·Коррозия, накладываемая Кастором на врагов «Церковь Фонарщиков», увеличивается на [Arg4]%."
