  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Данный талант активен только на уровнях «Звёздное Царство».\n·Телосложение, атака и защита данного Пробуждённого увеличиваются на [Arg1] %, а также он получает [Arg2] очков серебряной энергии при первом разыгрывании Возжигания ключесвета.\n·Огромная Огромная сила, полученная всеми Пробуждёнными, увеличивается на [Arg3]%.\n·Когда Клементина наносит Урон врагам «Насекомоподобное», на цель накладывается Эффект кровотечения на [Arg4]% от урона. При первом нанесении щита или восстановлении жизней за ход, Клементина временно лишает врагов «Насекомоподобное» защиты на [Arg5]% от силы."
  },
