  AwakerTalent_78911_TalentDesc_1 = {
    Text = "·Этот талант активен только в уровне «Звёздное Царство».\n·У этого пробуждённого увеличиваются Тело, атака и защита на [Arg1] %, и после первого разыгрывания Возжигания ключесвета этот пробуждённый получает [Arg2] очков ключесвета.\n·Урон, наносимый Безумием·Мёрфи, дополнительно накладывает [Arg3]% «Жертвоприношения», Эффект усиления «Ритуала рождения» от «Контракта судьбы» удваивается.\n·Когда в отряде присутствует 1/2/3 других пробуждённых «Лемурии», максимум здоровья увеличивается на 6%/15%/30%. Пробуждённые «Лемурии» после применения Взрыва безумия получают щит в размере 50%/125%/250% защиты Безумия·Мёрфи; этот Эффект срабатывает не более 1 раза за ход и не подвержен эффектам усиления щита."
  },
