  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·После нанесения урона картой команды Клементина получает 1 Уровень \"Эмпатии\".\n·Каждый раз, когда пробуждённое тело Клементина, Колесо Судьбы и ковенант дают 1 очко свойства ключесвета, крит. шанс и крит. Урон увеличиваются на 0,35%.\n·После начала ультра-хода удаляются все \"психические травмы\" и \"фобические фиксации\" у врагов. За каждое удаление 1 уровня \"психической травмы\" у врагов вы получаете 50 очков ключесвета, а за каждое удаление 1 уровня \"фобической фиксации\" другие пробуждающие тела получают 2 очка алиэмиуса."
  },
  AwakerTalent_79211_TalentName_1 = {
    Text = "Чутьё улья"
  },
  AwakerTalent_79788_TalentDesc_1 = {
    Text = "·Этот талант активен только в уровне «Звёздное Царство».\n·У этого пробуждённого увеличиваются Тело, атака и защита на [Arg1] %, и после первого разыгрывания Возжигания ключесвета этот пробуждённый получает [Arg2] очков ключесвета."
