  AwakerTalent_83778_TalentDesc_1 = {
    Text = "·Корпосант, его снаряжение, колесо судьбы и ковенант каждый предоставляют 1% сопротивления смерти, Базовый Урон увеличивается на 0.2%, щит увеличивается на 0.05%."
  },
  AwakerTalent_83778_TalentName_1 = {Text = "Пепел"},
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "·За каждый 1 Уровень восстановления алиемуса у Ауриты, при начале битвы получает Урон щупальцем в размере 2% от атаки Ауриты; за каждый 1% шанса крит. удара, при начале битвы получает Урон щупальцем в размере 1% от атаки Ауриты."
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "Весёлый дух"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·При первом использовании «Ониксового пера» за ход на всех врагов накладывается «Коррозия» в размере 840% от собственного АТК и получает 10 единиц Алиемуса. \n·За каждые 1% усиления урона Кастор увеличивает базовую «Коррозию» на 1%. \n·После окончания боя «Коррозия», наложенная Кастором в этом исследовании, увеличивается на 20% навсегда. \n·«Коррозия», наложенная в Босс Битве, удваивается. \n·После наложения «Коррозии» Кастор увеличивает свой Урон на 5% от наложенной «Коррозии» в этом раунде. \n·Урон, нанесенный Кастором, не удаляет «Коррозию»."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "Священные перья очищения"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "·Доресайн получает 1 «Обломок» после убийства врага или нанесения урона лидеру с помощью Алиемуса. \n·Максимум 3 «Обломка». \n·«Обломки» переносятся в следующий бой."
  },
  AwakerTalent_95804_TalentName_1 = {
    Text = "Расхищение гробов"
  },
